using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurgingAnchorAction", menuName = "Data/Battle/Battle Actions/Cellarius/PurgingAnchor Action")]
public class PurgingAnchorAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private int purifyAmountToIncrease;

	[SerializeField]
	private PlayerDiceInventoryData allDicePool;

	[SerializeField]
	private PlayerDiceInventoryData playerDrawPool;

	[SerializeField]
	private PlayerDiceInventoryData playerDiceDiscardPool;

	private bool toDrawPool;

	private bool isCasted;

	public PurifyAction PurifyAction => purifyAction;

	public int PurifyAmountToIncrease => purifyAmountToIncrease;

	public bool IsCasted => isCasted;

	public void SetToDrawPool(bool value)
	{
		toDrawPool = value;
	}

	public override void CastTargetAmount(GameObject target, int purifyAmount, GameObject source)
	{
		purifyAction.CastTargetAmount(target, purifyAmount, source);
		DiceInstance diceInstance = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance;
		isCasted = true;
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			isCasted = false;
			if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(diceInstance.ActionOwner))
			{
				_ = diceInstance.Dice;
				bool flag = false;
				if (diceInstance.OriginalDice.DiceName.Contains("Purging Anchor"))
				{
					flag = true;
				}
				if (target.GetComponent<CorruptionStats>().CurrentCorruption <= 0f && flag)
				{
					Dice dice = diceInstance.OriginalDice.InstantiateScriptableObjectTryingToCopyDiceFacesModded();
					for (int i = 0; i < diceInstance.Dice.GetDiceFaces().Length; i++)
					{
						DiceFace diceFace2 = diceInstance.Dice.GetDiceFaces()[i];
						DiceFace diceFace3 = dice.GetDiceFaces()[i];
						if (diceFace2.BattleAction == this)
						{
							ChangeDieFace(diceFace2);
							ChangeDieFace(diceFace3);
							diceFace2.UpdateActionValueModifier();
						}
					}
					allDicePool.DiceForged(diceInstance, dice);
				}
				if (toDrawPool)
				{
					playerDrawPool.IncreaseDiceAmount(diceInstance.OriginalDice, 1, insertAsFirst: false, updateDicePoolText: false);
				}
				else
				{
					playerDiceDiscardPool.IncreaseDiceAmount(diceInstance.OriginalDice, 1, insertAsFirst: false, updateDicePoolText: false);
				}
			}
		});
		void ChangeDieFace(DiceFace diceFace)
		{
			diceFace.ActionValue += purifyAmountToIncrease;
			diceFace.NewActionValue = diceFace.ActionValue;
			diceFace.NewBattleAction = diceFace.BattleAction;
			diceFace.KeepChanges = true;
		}
	}
}
